content.text:
plugins {
    id "com.android.application"
    id "kotlin-android"
    // The Flutter Gradle Plugin must be applied after the Android and Kotlin Gradle plugins.
    id "dev.flutter.flutter-gradle-plugin"
}

// Where keystore is locally stored.
def keystoreProperties = new Properties()
def keystorePropertiesFile = rootProject.file('key.properties')
if (keystorePropertiesFile.exists()) {
    keystorePropertiesFile.withReader('UTF-8') { reader ->
        keystoreProperties.load(reader)
    }
}

android {
    // ----- BEGIN flavorDimensions (autogenerated by flutter_flavorizr) -----
    flavorDimensions += "flavor-type"

    productFlavors {
        ni {
            dimension "flavor-type"
            applicationId "wemove.app.bipu"
            resValue "string", "app_name", "UmweltNAVI Niedersachsen"
        }
        sh {
            dimension "flavor-type"
            applicationId "de.wemove.umweltnavi.sh"
            resValue "string", "app_name", "UmweltNAVI Schleswig-Holstein"
